// Task 13 (QA) — regression (additive contract) + structural/negative probes for
// plugin-pipeline AC-1 / AC-3 / AC-4. These guard the surface most likely to
// silently regress: scan-library's shipped additive contract (proto + deps
// unchanged), the config-driven core (no media-type literals in orchestration
// code), and the parseTV extraction (TV parse lives ONLY in tv-parser).
//
// check.sh enforces ONLY golangci-lint + the exported-symbol budget; it does NOT
// enforce these architectural negatives. The task spec (task_13) MANDATES them as
// automated CI tests (INV-automated-probes) so a regression is caught. They are
// the justified carve-out from the code-quality "no source-text assertions" rule:
// these are NEGATIVE architectural invariants ("media logic must stay OUT of core";
// "parseTV must stay OUT of base-scanner") that have NO runtime expression — the
// only durable guard is source inspection. (AC-2 gate regression, AC-6 soft-fail,
// state-machine legality, and namespace rejection at the subprocess layer are
// covered by check.sh/depguard and the coder's unit + integration tests; see
// docs/plugin-pipeline/qa/.joint_coverage.md for the layer mapping.)
package itest

import (
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

// TestQA_AdditiveContract_ProtoAndDepsUnchanged is the AC-3 verify probe
// (acceptance.md): Phase A is additive (deprecate-don't-delete), so proto/ (no
// proto edits) must be byte-unchanged since the split-repo baseline f2dc2e8 (the
// repo root after the 2026-10-14 subtree split, where proto/ first lives at root
// level; no sanctioned proto change had landed since). The old pin 7bcc6c9
// (scan-library's shipped tip) cannot work here: its tree predates root-level
// proto/, so a diff against it reports the directory as all-insertions (13
// files, +4057) — vacuously failing on every run. Re-baselining to f2dc2e8
// preserves the guard's semantics: "no proto/ change since the sanctioned
// baseline". Re-baselined to 13e441a by media-data-convention 2.1 (the
// first sanctioned proto change since f2dc2e8).
// (go.mod/go.sum were previously guarded as "no new deps", but
// web-ui Phase 1 legitimately adds the first Go dependency —
// swaggo/http-swagger — so deps are no longer repo-wide-constant; forward
// additivity is each feature's AC-7 probe.)
// Runs `git diff --name-only`; skips cleanly when git or the commit is unavailable.
func TestQA_AdditiveContract_ProtoAndDepsUnchanged(t *testing.T) {
	if _, err := exec.LookPath("git"); err != nil {
		t.Skip("git not on PATH — cannot verify the additive proto/deps contract")
	}
	root := moduleRoot(t)
	if !qprCommitExists(t, root, "13e441a") {
		t.Skip("commit 13e441a not present — cannot verify additive contract (shallow clone?)")
	}
	for _, target := range []string{"proto/"} {
		if diff := qprDiffNames(t, root, "13e441a", target); diff != "" {
			t.Errorf("AC-3: additive contract broken — %s changed since 13e441a (deprecate-don't-delete):\n%s", target, diff)
		}
	}
}

// TestQA_ConfigDrivenCore_NoMediaLiterals is the AC-4 structural/negative probe:
// the orchestrator core selects plugins STRICTLY from module config, so NO
// media-type literal ("tv"/"tmdb"/"kinopoisk"/"movie") may appear in core
// orchestration code. Media-type names are sanctioned ONLY in internal/module
// seed config (the config entity names media types) and tests — hence the scan
// excludes internal/module. The QUOTED-literal form is used so legitimate
// non-branching occurrences (the store's tmdb_id/kinopoisk_id SQL columns, the
// tv-parser plugin id) are not false positives — none of those is a quoted
// media-type literal.
func TestQA_ConfigDrivenCore_NoMediaLiterals(t *testing.T) {
	root := moduleRoot(t)
	// Orchestrator packages (core); internal/module is the config home (excluded).
	pkgs := []string{
		"internal/api", "internal/enrich", "internal/plugin",
		"internal/scan", "internal/store", "pkg/sdk", "cmd/mellifera",
	}
	literals := []string{`"tv"`, `"tmdb"`, `"kinopoisk"`, `"movie"`}
	for _, pkg := range pkgs {
		if hits := qprHits(root, pkg, literals); len(hits) > 0 {
			t.Errorf("AC-4: media-type literal in core orchestration %s (must be config-driven only): %v", pkg, hits)
		}
	}
}

// TestQA_ParseTVExtractionBoundary is the AC-1 structural/negative probe: parseTV
// and its TV field tokens (season/episode/SxxExx) live ONLY in plugins/tv-parser
// after the Task 06/07 extraction; plugins/base-scanner is media-type-agnostic.
// Asserts base-scanner non-test code has ZERO such tokens and tv-parser has the
// moved parseTV.
func TestQA_ParseTVExtractionBoundary(t *testing.T) {
	root := moduleRoot(t)
	if hits := qprHits(root, "plugins/base-scanner", []string{"parseTV", "SxxExx", "season", "episode"}); len(hits) > 0 {
		t.Errorf("AC-1: base-scanner (media-type-agnostic) carries TV-parse tokens — parseTV must live in tv-parser only: %v", hits)
	}
	if hits := qprHits(root, "plugins/tv-parser", []string{"parseTV"}); len(hits) == 0 {
		t.Errorf("AC-1: tv-parser missing parseTV (the verbatim move from base-scanner)")
	}
}

// qprCommitExists reports whether the given commit is resolvable in the repo at root.
func qprCommitExists(t *testing.T, root, sha string) bool {
	t.Helper()
	cmd := exec.Command("git", "rev-parse", "--verify", fmt.Sprintf("%s^{commit}", sha))
	cmd.Dir = root
	return cmd.Run() == nil
}

// qprDiffNames returns the `git diff --name-only <sha> -- <target>` output (one
// changed path per line) for the repo at root. Empty output = no changes.
func qprDiffNames(t *testing.T, root, sha, target string) string {
	t.Helper()
	cmd := exec.Command("git", "diff", "--name-only", sha, "--", target)
	cmd.Dir = root
	out, err := cmd.Output()
	if err != nil {
		t.Fatalf("AC-3: git diff %s -- %s failed: %v", sha, target, err)
	}
	return strings.TrimSpace(string(out))
}

// qprHits walks the non-test .go files under root/dir and returns the de-commented
// occurrences of any token, as "relpath:line <token>" strings. Comments (everything
// after "//") are stripped so a token mentioned only in a comment does not count.
func qprHits(root, dir string, tokens []string) []string {
	files := qprNonTestGo(root, dir)
	var hits []string
	for _, f := range files {
		data, err := os.ReadFile(f)
		if err != nil {
			continue
		}
		rel, _ := filepath.Rel(root, f)
		for i, line := range strings.Split(string(data), "\n") {
			code := qprCodePart(line)
			for _, tok := range tokens {
				if strings.Contains(code, tok) {
					hits = append(hits, fmt.Sprintf("%s:%d %s", rel, i+1, tok))
				}
			}
		}
	}
	return hits
}

// qprNonTestGo lists the non-test .go files directly under root/dir (these packages
// are flat — no nested subdirs).
func qprNonTestGo(root, dir string) []string {
	matches, err := filepath.Glob(filepath.Join(root, dir, "*.go"))
	if err != nil {
		return nil
	}
	out := matches[:0]
	for _, m := range matches {
		if !strings.HasSuffix(m, "_test.go") {
			out = append(out, m)
		}
	}
	return out
}

// qprCodePart strips a trailing "//" line comment so only the code portion is
// inspected. (A "//" inside a string literal would over-truncate, but none of the
// scanned files contains that pattern; the goal is to ignore comment-only mentions.)
func qprCodePart(line string) string {
	if i := strings.Index(line, "//"); i >= 0 {
		return line[:i]
	}
	return line
}
